      SUBROUTINE GGETCC     VALUES OF PARAMETERS DESCRIBING QUADRUPOLECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      EXTERNAL        DATAR, IDATAC---------------------------------------------------------------CC     MAGNET LENGTHC      IADR = I + 1      L = DATAR(IADR)      IF (PRAN5(1) .NE. 0.0) L = L + PRAN5(1)*XRAN(1)      L = L*UNITI(8)      LMAG = LCC     INDICES FOR OTHER PARAMETERSC      IB = IPTOJ(2)      IAP = IPTOJ(3)      IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (IG .NE. 0) GO TO 10      IF (IK1 .NE. 0) GO TO 20      IF (IB .NE. 0) GO TO 5      KQ2 = 0.0      GO TO 40CC     MAGNETIC FIELD AND APERTUREC    5 IADR = I + IB      B = DATAR(IADR)      IF (PRAN5(2) .NE. 0.0) B = B + PRAN5(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      IF (IAP .NE. 0) THEN        IADR = I + IAP        AP = DATAR(IADR)      ELSE        WRITE (NOUT,9008) 9008   FORMAT (' *** ERROR *** QUADRUPOLE APERTURE NOT GIVEN')        FLUSHL = .TRUE.        KQ2 = 0.0        AP = 0.0        GO TO 40      ENDIF      IF (NORD1 .LT. 1) GO TO 40      IF (AP .NE. 0.0) THEN        IF (PRAN5(3) .NE. 0.0) AP = AP + PRAN5(3)*XRAN(3)        AP = AP*UNITI(1)        KQ2 = B/(AP*RI)      ELSE        WRITE (NOUT,9005) 9005   FORMAT (' *** ERROR *** QUADRUPOLE APERTURE SET TO ZERO')        FLUSHL = .TRUE.        KQ2 = 0.0      ENDIF      GO TO 40CC     GRADIENTC   10 IADR = I + IG      GRAD = DATAR(IADR)      IF (PRAN5(4) .NE. 0.0) GRAD = GRAD + PRAN5(4)*XRAN(4)      GRAD = GRAD*UNITI(9)*RI/(PREF*UNITI(1))      KQ2 = GRAD/RI      GO TO 40CC     K1 (NORMALIZED GRADIENT)C   20 IADR = I + IK1      K1 = DATAR(IADR)      IF (PRAN5(5) .NE. 0.0) K1 = K1 + PRAN5(5)*XRAN(5)      KQ2 = K1/UNITI(8)**2C   40 IT = IPTOJ(7)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END